          data-testid="setting-policy-date"
          [value]="policyDate()"
          (input)="policyDate.set(value($event)); policyDateTouched.set(true); error.set(null)"
          (focus)="focused.set('policy-date')"
          (keydown.delete)="policyDateTouched.set(true); error.set(null)"
